// ===== 段评功能() =====
function getComments(content, bookId, itemId) {
  var java = this.java, cache = this.cache;
  try {
    var separator = '\n';
    if (/<p>/.test(content)) { content = content.replace('<p>','').replace(/<\/p>/g, '').replace('\n', ''); separator = '<p>'; } else { content = content.replace(/\r/g, '').replace(/\n$/, ''); }
    var comcont = content.split(separator);
comcont.forEach((item, idx) => {
comcont[idx] = item.replace(/[\r\n]/g, '').trim();
});
    var url = `https://fqdp.mlds.dpdns.org/api/idea/summary?book_id=${bookId}&item_id=${itemId}`;
    var comments = JSON.parse(java.ajax(url));
    comments = comments.data;

    var commentList = [];

Object.entries(comments).forEach(([paragraphId, { count }]) => {
  commentList.push({
    paragraphId: paragraphId,
    textCount: count
  });
});

    if (commentList.length == 0) { return content; }
    commentList.forEach(function(x) {
        if (comcont[x.paragraphId]) {
//java.toast(JSON.stringify(x));
            comcont[x.paragraphId] += '<img src="' + createSvg.call({source: this.source, java: java, cache: cache}, x.textCount, bookId, itemId, x.paragraphId) + '">';
        }
    }.bind(this));
    return comcont.join('\n');
  } catch (e) { java.log(e); return content; }
}
function createSvg(number, bookId, itemId, para_index) {
  const { java, cache, source } = this;

  var qpyscolor = '#A9A9A9', qpwzcolor = '#A9A9A9', size = 'text';
    try { var c1 = source.getLoginInfoMap().get('气泡颜色'); if (c1 && c1 != '') qpyscolor = c1; } catch(e) {}
    try { var c2 = source.getLoginInfoMap().get('数字颜色'); if (c2 && c2 != '') qpwzcolor = c2; } catch(e) {}
    try { var s = source.getLoginInfoMap().get('大小'); if (s && s != '') size = s; } catch(e) {}
  var displayText = number > 99 ? '99' : number;

var svg = '<svg viewBox="5 14 45 36" xmlns="http://www.w3.org/2000/svg" width="180" height="144"><path d="M44 48 Q48 48 48 44 L48 20 Q48 16 44 16 L20 16 Q16 16 16 20 L16 24 S16 28 10 30 Q6 32 10 34 Q16 36 16 38 L16 44 Q16 48 20 48 Z" fill="none" stroke="' + qpyscolor + '" stroke-width="0.7"/><text x="32" y="38" text-anchor="middle" font-family="Arial, sans-serif" font-weight="600" font-size="18" fill="' + qpwzcolor + '" dominant-baseline="middle">' + displayText + '</text></svg>';

try {
let bbSvg = GET.call(this, 'bbSvg');
if (bbSvg && bbSvg != '') { svg = bbSvg.split('{n}').join(displayText).split('{c}').join(qpyscolor).split('{t}').join(qpwzcolor); }
} catch(e) {}

  var encodedSvg = java.base64Encode(svg);
  var clickObj = { style: size, type: "bubble", click: "showCmt('" +  bookId + "','" + itemId + "','" + para_index + "','" + number + "')" };

  return 'data:image/svg+xml;base64,' + encodedSvg + ',' + JSON.stringify(clickObj);
}

